#!/bin/bash
PID=$(pgrep -f 'node.*server\.js' | head -1)
DATABASE_URL=$(cat /proc/$PID/environ | tr '\0' '\n' | grep '^DATABASE_URL=' | cut -d= -f2-)

node << 'EONODE'
const {Client}=require('/var/app/current/node_modules/pg');
const {execSync}=require('child_process');
const pid=execSync("pgrep -f 'node.*server\.js' | head -1").toString().trim();
const env=require('fs').readFileSync('/proc/'+pid+'/environ','utf8');
const vars=Object.fromEntries(env.split(String.fromCharCode(0)).filter(Boolean).map(e=>{const i=e.indexOf('=');return[e.slice(0,i),e.slice(i+1)];}));
const db=new Client({connectionString:vars.DATABASE_URL,ssl:{rejectUnauthorized:false}});
db.connect().then(async()=>{
  // Check advisory locks
  const r1=await db.query("SELECT pid, classid, objid, granted FROM pg_locks WHERE locktype='advisory'");
  console.log('Advisory locks:', JSON.stringify(r1.rows));
  // Check blocking queries
  const r2=await db.query("SELECT pid, state, wait_event_type, wait_event, query_start, LEFT(query,100) AS q FROM pg_stat_activity WHERE state != 'idle' ORDER BY query_start");
  console.log('Active queries:', JSON.stringify(r2.rows));
  await db.end();
}).catch(e=>{console.error(e.message);process.exit(1);});
EONODE
